// Generated by `purlis artifact types` from purlis's query catalogue (ADR 0122 §7). Do not edit:
// generate it again when purlis moves.
//
// A page's script reaches purlis only through `purlis.port`. It declares what it reads in its
// index.html, and anything undeclared answers `not-approved`:
//
//   <script type="application/json" id="purlis">
//     { "api": 1, "data": ["data.json"], "queries": { "purlis.todo_list@1": ["done"] } }
//   </script>
//
// `purlis artifact check <folder>` checks the declaration against the catalogue, and
// `purlis artifact mock` prints a port that answers from purlis-fixtures.json, for a page opened
// outside purlis.

declare namespace PurlisPage {
  /** Why an answer has no data. */
  type ErrorKind = "needs-extension" | "not-approved" | "timeout" | "too-large" | "refused" | "failed";

  /** Every answer: its data or why there is none (with a sentence for the reader, where purlis has one), when it was answered, and where its next page starts. */
  type Envelope<T> =
    | { data: T; at: string; cursor?: string; error?: never }
    | { error: { kind: ErrorKind; message?: string }; at: string; data?: never; cursor?: never };

  /** What the port answers an ask with: its envelope and the ask's `id`, or `null` for an ask that was no ask. */
  type Answer<T = unknown> = Envelope<T> & { id: number | null };

  /** Every query this purlis answers, as a page declares and asks it: `<id>@<N>`. */
  interface Queries {
    /** List the open todos of the workspace this chat works in, oldest first, each with the slug todo_done closes it by. With done, the done todos instead, each with the slug todo_reopen opens it again by, as `purlis ws todo --done` lists them. */
    "purlis.todo_list@1": {
      params: {
        /** List the done todos instead of the open ones. */
        done?: boolean;
      };
      data: {
        /** Whether these are the done todos. */
        done: boolean;
        todos: Array<{
          /** What todo_done closes it by, or todo_reopen opens it again by. */
          slug: string;
          /** Its title. */
          title: string;
          /** When it was recorded, as its file says it (YYYY-MM-DD HH:MM), or empty. */
          opened: string;
        }>;
      };
    };
    /** Search the memory of the workspace this chat works in: the best 8 matches for a query. With no query, the newest 20 memories, newest first, and a cursor to the 20 before them. */
    "purlis.memory_search@1": {
      params: {
        /** Words to look for. */
        query?: string;
        /** With no query: the cursor the last answer gave, for the memories older than it showed. */
        cursor?: string;
      };
      data: {
        memories: Array<{
          /** Its file name in the workspace's memory. */
          file: string;
          /** Its title. */
          title: string;
          /** Its whole text, as written. */
          text: string;
        }>;
      };
    };
    /** List the session records of where this chat works (its workspace, or the project root), newest first. */
    "purlis.session_record_list@1": {
      params: Record<string, never>;
      data: {
        records: Array<{
          /** Its file name, which session_record_read reads it by. */
          file: string;
          /** Its title, or its file name when it has none. */
          title: string;
          /** When it was written, YYYY-MM-DD HH:MM. */
          when: string;
        }>;
      };
    };
    /** Read one session record of where this chat works, by its file name (session_record_list shows it). */
    "purlis.session_record_read@1": {
      params: {
        /** The record's file name, YYYYMMDD-HHMMSS-<title>.md. Never a path. */
        file: string;
      };
      data: {
        /** Its file name. */
        file: string;
        /** Its whole text, as written. */
        text: string;
      } | null;
    };
    /** The cross-repo changes of this workspace: with no change named, one line each; with one, its record (why, members, branches and what each needs). The forge is not asked: run `purlis change show` for that. */
    "purlis.change_status@1": {
      params: {
        /** The change's slug. */
        change?: string;
      };
      data: {
        changes: Array<{
          /** Its name. */
          change: string;
          /** Why it is being made. */
          why: string;
          /** When it was created. */
          created: string;
          /** Who created it. */
          by: string;
          members: Array<{
            /** The repo. */
            repo: string;
            /** Its branch there. */
            branch: string;
            needs: string[];
          }>;
          excluded: Array<{
            /** The repo left out. */
            repo: string;
            /** Why. */
            why: string;
          }>;
        }>;
        unreadable: Array<{
          /** The name of a record that could not be read. */
          change: string;
          /** Why. */
          why: string;
        }>;
      };
    };
    /** The milestones of a GitHub repo of this workspace, each with its open and closed issue counts, due date and page. Only a repo whose clone is in this workspace; the open milestones unless state is all. */
    "purlis.forge_milestones@1": {
      params: {
        /** The repo of this workspace, by its folder's name. Leave it out when the workspace has one repo. */
        repo?: string;
        /** open (the default) for the open milestones, or all for the closed ones too. */
        state?: "open" | "all";
      };
      data: {
        /** The repo of this workspace, by its folder's name. */
        repo: string;
        /** Its owner/name on GitHub. */
        path: string;
        /** open or all, as asked. */
        state: string;
        milestones: Array<{
          /** Its number on GitHub. */
          number: number;
          /** Its title. */
          title: string;
          /** Its description, or empty. */
          description: string;
          /** When it is due (RFC 3339), or null. */
          due_on: string | null;
          /** open or closed. */
          state: string;
          /** How many of its issues are open. */
          open_issues: number;
          /** How many of its issues are closed. */
          closed_issues: number;
          /** Its page on GitHub. */
          url: string;
          /** When it last changed (RFC 3339). */
          updated_at: string;
        }>;
      };
    };
  }

  type QueryId = keyof Queries;

  /** One action a page offers: a row of purlis's action catalogue (`todo.done`) and its subject. */
  interface Offer {
    does: string;
    subject: string;
  }

  /** What the port is asked: a data file the page declared, a query it declared, or the whole set of actions it offers now (at most 8). */
  type Ask =
    | { id: number; read: string }
    | { [K in QueryId]: { id: number; query: K; params?: Queries[K]["params"] | null } }[QueryId]
    | { id: number; offers: Offer[] };

  /** What an offer set is answered: how many purlis took. */
  interface Offered {
    offered: number;
  }

  interface Port extends MessagePort {
    postMessage(ask: Ask): void;
    onmessage: ((this: MessagePort, event: MessageEvent<Answer>) => void) | null;
  }

  interface Page {
    /** The API version purlis answers this page in. */
    readonly api: 1;
    readonly port: Port;
  }

  /** One query's fixture: its envelope without `at`, which the mock answers with the time it answers. */
  type Fixture<T> = { data: T; cursor?: string } | { error: { kind: ErrorKind; message?: string } };

  /** What the mock answers from, in purlis-fixtures.json beside the page. A data file with no fixture is fetched from the page's folder. */
  interface Fixtures {
    data?: Record<string, unknown>;
    queries?: { [K in QueryId]?: Fixture<Queries[K]["data"]> };
  }
}

/** purlis's port for this page: in purlis, purlis's own; outside it, the mock's. */
declare var purlis: PurlisPage.Page;
